import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.C2TvIV46.js";const m=JSON.parse('{"title":"Team or player target","description":"","frontmatter":{},"headers":[],"relativePath":"language/enums/team-or-player-target.md","filePath":"language/enums/team-or-player-target.md"}'),n={name:"language/enums/team-or-player-target.md"};function d(r,e,l,c,p,i){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="team-or-player-target" tabindex="-1">Team or player target <a class="header-anchor" href="#team-or-player-target" aria-label="Permalink to &quot;Team or player target&quot;">​</a></h1><p>Operand syntax for actions that apply to a specific player, a specific team, or all players. In ManagedMegalo grammar this appears as <code>&lt;team_or_player_target&gt;</code>; on the wire it is stored as <code>s_team_or_player_target</code> with a two-bit kind field <code>e_action_team_or_player_target</code> in @blamnetwork/blf.</p><p>Used by <a href="/MegaloEvolved/beta/docs/language/actions/set-score"><code>set_score</code></a>, <a href="/MegaloEvolved/beta/docs/language/actions/play-sound"><code>play_sound</code></a>, and <a href="/MegaloEvolved/beta/docs/language/actions/hud-post-message"><code>hud_post_message</code></a>. <a href="/MegaloEvolved/beta/docs/language/actions/submit-incident"><code>submit_incident</code></a> uses the same underlying type for its <code>&lt;cause_team_or_player&gt;</code> and <code>&lt;effect_team_or_player&gt;</code> operands.</p><h2 id="kind-keywords" tabindex="-1">Kind keywords <a class="header-anchor" href="#kind-keywords" aria-label="Permalink to &quot;Kind keywords&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Keyword</th><th>blf enum</th><th>Meaning</th></tr></thead><tbody><tr><td><code>team</code></td><td><code>team</code></td><td>A specific team — followed by a <a href="/MegaloEvolved/beta/docs/language/references#team-designators">team reference</a></td></tr><tr><td><code>player</code></td><td><code>player</code></td><td>A specific player — followed by a <a href="/MegaloEvolved/beta/docs/language/references#reference-types">player reference</a></td></tr><tr><td><code>everyone</code></td><td><code>all_players</code></td><td>All players in the session</td></tr></tbody></table><p>Scripts spell the all-players kind as <code>everyone</code>. The blf enum name is <code>all_players</code>.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>team &lt;team_ref&gt;</span></span>
<span class="line"><span>player &lt;player_ref&gt;</span></span>
<span class="line"><span>everyone</span></span></code></pre></div><p>Team and player kinds always include their reference on the next token(s). The <code>everyone</code> kind stands alone.</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action set_score add kill_points player killing_player</span></span>
<span class="line"><span class="megalo-text">action set_score add </span><span class="megalo-number">1</span><span class="megalo-text"> team attackers</span></span>
<span class="line"><span class="megalo-text">action play_sound everyone ctf</span></span>
<span class="line"><span class="megalo-text">action play_sound team defenders bone_cv_ph1_intro</span></span>
<span class="line"><span class="megalo-text">action hud_post_message everyone none </span><span class="megalo-string">&quot;Round started!&quot;</span></span>
<span class="line"><span class="megalo-text">action submit_incident game_start_slayer everyone everyone</span></span></code></pre></div><h2 id="not-the-same-as-audience-operands" tabindex="-1">Not the same as audience operands <a class="header-anchor" href="#not-the-same-as-audience-operands" aria-label="Permalink to &quot;Not the same as audience operands&quot;">​</a></h2><p>Several actions take an <strong>audience</strong> operand (<code>everyone</code>, <code>allies</code>, <code>enemies</code>, <code>player</code>, <code>team</code>, <code>no_one</code>) that filters who sees a navpoint, boundary, progress bar, or pickup rule. That is a different type (<code>c_player_filter_modifier</code>) even though some keywords overlap.</p><table tabindex="0"><thead><tr><th>Use case</th><th>Operand type</th><th>Example actions</th></tr></thead><tbody><tr><td>Score, sound, HUD message, incidents</td><td>Team or player target</td><td><code>set_score</code>, <code>play_sound</code>, <code>hud_post_message</code>, <code>submit_incident</code></td></tr><tr><td>Visibility and pickup filters</td><td>Audience</td><td><code>navpoint_set_visible</code>, <code>boundary_set_visible</code>, <code>set_pickup_filter</code></td></tr></tbody></table><p>See <a href="/MegaloEvolved/beta/docs/language/references#audience-references">References — Audience references</a> for the audience list.</p><h2 id="related-operands" tabindex="-1">Related operands <a class="header-anchor" href="#related-operands" aria-label="Permalink to &quot;Related operands&quot;">​</a></h2><p><a href="/MegaloEvolved/beta/docs/language/actions/set-loadout"><code>set_loadout</code></a> grammar uses <code>&lt;team_or_player&gt;</code> with the same <code>team</code> / <code>player</code> prefix pattern but only those two kinds (no <code>everyone</code>).</p>`,16)])])}const h=a(n,[["render",d]]);export{m as __pageData,h as default};
